async function refreshTeacher(){
 if(saving||syncTimer||busy)return;
 const response=await fetch('/api/teacher/state');if(response.status===401){location.reload();return}if(!response.ok)throw new Error('교사 데이터를 불러오지 못했습니다.');const data=await response.json();
 if(saving||syncTimer||busy)return;
 if(data.revision===serverRevision)return;
 const selected=db.classId;db=data.state;if(db.classes.some(c=>c.id===selected))db.classId=selected;
 db.studentAccess=Object.fromEntries(data.access.map(a=>[a.studentId,a]));serverRevision=data.revision;teacherRevision=data.teacherRevision;
 if(teacherAi&&!db.apiBase&&!db.demoOverride)db.apiBase=location.origin+'/api';
 const focused=document.activeElement?.tagName;if(!['INPUT','TEXTAREA','SELECT'].includes(focused)&&!draft&&!(page==='materials'&&selectedMaterialId))render();
}
